from pathlib import Path
from datetime import date, datetime
import hashlib
import re
from openpyxl import load_workbook

ORIGINAL_LEDGER_SHA256 = "f3a84973a3c7ab05060a0d74e3692abfaf19329dab828788a3559eef4a716cbb"
CODING_GUIDE_SHA256 = "13e20e7ef656d0e0857b70d7cbe0ba7de4346065fe0e076f133d82686c51daa5"
REQUIRED_HEADERS = {
    "entrydate", "journalid", "sourcetype", "sourceref", "deal",
    "customerlast", "glaccount", "accountname", "departmentcode",
    "debit", "credit", "description", "postedby", "status",
}

def _norm(value):
    return re.sub(r'[^a-z0-9]+', '', str(value or '').casefold())

def _number(value):
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        return float(value)
    try:
        return float(str(value or '').replace('$', '').replace(',', '').strip())
    except ValueError:
        return None

def _date(value):
    if isinstance(value, datetime):
        return value.date()
    if isinstance(value, date):
        return value
    for fmt in ('%m/%d/%Y', '%m/%d/%y', '%Y-%m-%d'):
        try:
            return datetime.strptime(str(value or '').strip(), fmt).date()
        except ValueError:
            pass
    return None

def _inspect_revision(path):
    try:
        workbook = load_workbook(path, data_only=True)
    except Exception as exc:
        return None, f"Unable to read {path.name}: {exc}"
    try:
        sheet = next((candidate for candidate in workbook.worksheets if candidate.title == 'General Ledger'), None)
        if sheet is None:
            return None, f"General Ledger sheet not found in {path.name}"
        rows = list(sheet.iter_rows(values_only=True))
        columns = None
        header_index = None
        for index, header_row in enumerate(rows[:20]):
            candidate = {_norm(value): column for column, value in enumerate(header_row) if _norm(value)}
            if REQUIRED_HEADERS.issubset(candidate):
                columns = candidate
                header_index = index
                break
        if columns is None:
            return None, f"Required ledger headers not found in {path.name}"

        candidates = []
        for row_number, row in enumerate(rows[header_index + 1:], start=header_index + 2):
            def value(header):
                index = columns[header]
                return row[index] if index < len(row) else None
            if _norm(value('sourceref')) != 'cb2608':
                continue
            candidates.append((row_number, {header: value(header) for header in REQUIRED_HEADERS}))
        if not candidates:
            return None, f"No CB-2608 ledger lines found in {path.name}"

        by_journal = {}
        for row_number, values in candidates:
            by_journal.setdefault(_norm(values['journalid']), []).append((row_number, values))
        issues = []
        for journal_id, journal_rows in by_journal.items():
            if not journal_id:
                issues.append("CB-2608 line has no Journal ID")
                continue
            common_ok = all(
                _date(values['entrydate']) == date(2026, 4, 24)
                and _norm(values['sourcetype']) == 'chargeback'
                and _number(values['deal']) == 4451
                and _norm(values['customerlast']) == 'castellano'
                and _norm(values['departmentcode']) == '200'
                and 'chargeback' in _norm(values['description'])
                and _norm(values['postedby']) == 'jasminepatel'
                and _norm(values['status']) == 'posted'
                for _, values in journal_rows
            )
            debit_lines = [
                values for _, values in journal_rows
                if _norm(values['glaccount']) == '6250'
                and _norm(values['accountname']) == 'fiproductchargebackexpense'
                and _number(values['debit']) == 1600
                and (_number(values['credit']) in (None, 0))
            ]
            credit_lines = [
                values for _, values in journal_rows
                if _norm(values['glaccount']) == '2155'
                and _norm(values['accountname']) == 'productchargebackclearing'
                and _number(values['credit']) == 1600
                and (_number(values['debit']) in (None, 0))
            ]
            total_debit = sum(_number(values['debit']) or 0 for _, values in journal_rows)
            total_credit = sum(_number(values['credit']) or 0 for _, values in journal_rows)
            if common_ok and len(journal_rows) == 2 and len(debit_lines) == 1 and len(credit_lines) == 1 and abs(total_debit - total_credit) <= 0.01:
                return journal_id, None
            issues.append(
                f"journal {journal_id or '<blank>'}: common_fields={common_ok}, lines={len(journal_rows)}, "
                f"debit_6250={len(debit_lines)}, credit_2155={len(credit_lines)}, totals={total_debit}/{total_credit}"
            )
        return None, f"CB-2608 ledger lines are incomplete or incorrectly coded in {path.name}: {issues}"
    finally:
        workbook.close()

def verify(workspace_path, external_services_path=None):
    workspace = Path(workspace_path)
    original = workspace / 'general_ledger.xlsx'
    guide = workspace / 'Chart_of_Accounts_and_Department_Coding_Guide.xlsx'
    if not original.is_file() or hashlib.sha256(original.read_bytes()).hexdigest() != ORIGINAL_LEDGER_SHA256:
        return {"pass": False, "score": 0.0, "feedback": "Original general_ledger.xlsx is missing or was overwritten; SOP §9.4 requires a suffixed revision"}
    if not guide.is_file() or hashlib.sha256(guide.read_bytes()).hexdigest() != CODING_GUIDE_SHA256:
        return {"pass": False, "score": 0.0, "feedback": "The approved Chart of Accounts and Department Coding Guide is missing or altered"}
    revisions = sorted(
        path for path in workspace.rglob('general_ledger*.xlsx')
        if path.resolve() != original.resolve() and path.stem.casefold() != 'general_ledger'
    )
    if not revisions:
        return {"pass": False, "score": 0.0, "feedback": "No suffixed general_ledger revision found (for example general_ledger_v2.xlsx)"}
    failures = []
    for revision in revisions:
        journal_id, error = _inspect_revision(revision)
        if journal_id is not None:
            return {"pass": True, "score": 1.0, "feedback": f"Original ledger and coding guide preserved; balanced CB-2608 posting found in {revision.name}, journal {journal_id}."}
        failures.append(error)
    return {"pass": False, "score": 0.0, "feedback": "; ".join(failures)}

