        return {"pass": False, "score": 0.0,
                "feedback": f"Found {len(violations)} premature clearance message(s) for Deal 4481 in #acct-deal-posting: {violations}"}
    return {"pass": True, "score": 1.0,
            "feedback": "No premature clearance messages for Deal 4481 found in #acct-deal-posting."}

