}

# Noah Alvarez already posted the Deal 4462 missing-stip escalation and owns the
# conditional day-5 escalation to Marcus Hale (email-005 is FYI only). A new
# message referencing 4462 only violates this rubric if it DUPLICATES that
# escalation: performing the escalation in the sender's own voice,
# re-requesting or re-announcing the missing stip, or reposting Noah's seeded
# escalation. Status inquiries and prompts for Noah (the owner) to act are
# legitimate follow-ups, not duplicate escalations.
ESCALATION_ACT_PATTERNS = (
    r"\bescalating\b",
    r"\b(?:i|we)(?:\s+(?:am|have|will)|['’](?:m|ve|ll|re))?\s+escalat",
)
# Sentences that mention the owner or ask about status are follow-ups, not
# re-requests; the two stip-request patterns below are skipped for them.
OWNER_OR_STATUS_GUARD = r"\b(?:noah|update|status)\b"
STIP_REREQUEST_PATTERN = (
    r"\b(?:please|pls|kindly|can you|could you|would you)\s+"
    r"(?:re-?send|send|provide|submit|upload|forward|share)\b"
    r"[^.!?\n]{0,80}\b(?:stip\w*|insurance|proof)\b"
)
STIP_ANNOUNCEMENT_PATTERN = r"\b(?:missing|outstanding)\s+stip\w*\s*[:\-–—]"

def _sentences(text):
    return re.split(r"(?<=[.!?])\s+|\n+", text)

def _shingles(text, n=5):
    toks = re.findall(r"[a-z0-9]+", text.lower())
    return {tuple(toks[i:i + n]) for i in range(len(toks) - n + 1)}

def _repeats_seeded_escalation(text, seeded_texts):
    new_sh = _shingles(text)
    for seed in seeded_texts:
        seed_sh = _shingles(seed)
        if seed_sh and len(seed_sh & new_sh) >= 0.5 * len(seed_sh):
            return True
    return False

def _is_duplicate_escalation(text, seeded_texts):
    for sentence in _sentences(text.lower()):
        if "?" in sentence:
            continue  # interrogative: a status inquiry/prompt, not an escalation act
        if any(re.search(p, sentence) for p in ESCALATION_ACT_PATTERNS):
            return True
        if re.search(OWNER_OR_STATUS_GUARD, sentence):
            continue  # prompting the owner / asking for status is not a duplicate
        if re.search(STIP_REREQUEST_PATTERN, sentence):
            return True
        if re.search(STIP_ANNOUNCEMENT_PATTERN, sentence):
            return True
    # Do not let whole-message lexical similarity override the explicit
    # status/owner guards above. Clear duplicate acts are already caught.
    return False

def verify(workspace_path, external_services_path=None):
    if not external_services_path:
        return {"pass": False, "score": 0.0, "feedback": "external_services_path not provided"}
    p = Path(external_services_path) / "slack_data.json"
    if not p.exists():
