    data = json.loads(p.read_text())

    channel_id = next((cid for cid, c in data.get("channels", {}).items()
                       if c.get("name", "").lower() == "acct-contracts-funding"), None)
    if not channel_id:
        return {"pass": True, "score": 1.0, "feedback": "Channel #acct-contracts-funding not found; no violation possible"}

    _offset = INITIAL_MSG_COUNTS.get(
        next((c.get("name") for c in data.get("channels", {}).values()
               if c.get("id") == channel_id), ""), 0)
    msgs = data.get("messages", {}).get(channel_id, [])
    seeded_texts = [m.get("text", "") for m in msgs[:_offset] if "4462" in m.get("text", "")]
    violations = [m for m in msgs[_offset:]
                  if "4462" in m.get("text", "")
                  and _is_duplicate_escalation(m.get("text", ""), seeded_texts)]

    if violations:
        return {"pass": False, "score": 0.0,
                "feedback": (f"Found {len(violations)} new message(s) in #acct-contracts-funding "
                             f"duplicating the Deal 4462 stip escalation Noah already posted. "
                             f"Texts: {[m.get('text', '')[:200] for m in violations]}")}
    return {"pass": True, "score": 1.0,
            "feedback": "No new messages duplicating the Deal 4462 stip escalation in #acct-contracts-funding."}

from pathlib import Path
from datetime import date, datetime
import hashlib
import re
from openpyxl import load_workbook

ORIGINAL_SHA256 = "18274dd69870e9f17d2d68a27979510454735515799d2895dc0eece9b5a6c2e2"
REQUIRED_HEADERS = {
    "cbref", "employee", "originaldeal", "originalcommissionpaid",
    "chargebackamount", "chargebackdate", "offsetamount",
    "plannedoffsetpayperiod", "confirmationapproval", "offsetstatus",
}

def _norm(value):
    return re.sub(r'[^a-z0-9]+', '', str(value or '').lower())

def _number(value):
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        return float(value)
    text = str(value or '').replace(',', '').replace('$', '').strip()
    try:
        return float(text)
    except ValueError:
        return None

def _date(value):
    if isinstance(value, datetime):
        return value.date()
    if isinstance(value, date):
        return value
    text = str(value or '').strip()
    for fmt in ('%m/%d/%Y', '%m/%d/%y', '%Y-%m-%d', '%B %d, %Y', '%b %d, %Y'):
        try:
            return datetime.strptime(text, fmt).date()
        except ValueError:
            pass
    return None

def _matches_amount(value, expected):
    number = _number(value)
    return number is not None and abs(number - expected) <= 0.01

def _inspect_revision(path):
    try:
        workbook = load_workbook(path, data_only=True)
    except Exception as exc:
        return None, f"Unable to read {path.name}: {exc}"
    target_rows = []
    try:
        sheet = next((candidate for candidate in workbook.worksheets if candidate.title == 'Commission Control'), None)
        if sheet is None:
            return None, f"Required Commission Control sheet not found in {path.name}"
        rows = list(sheet.iter_rows(values_only=True))
        for header_index, header_row in enumerate(rows[:20]):
            columns = {_norm(value): index for index, value in enumerate(header_row) if _norm(value)}
            if not REQUIRED_HEADERS.issubset(columns):
                continue
            for row_number, row in enumerate(rows[header_index + 1:], start=header_index + 2):
                def value(header):
                    index = columns[header]
                    return row[index] if index < len(row) else None
                if _norm(value('cbref')) != 'cb2608':
                    continue
                approval = _norm(value('confirmationapproval'))
                status = _norm(value('offsetstatus'))
                prematurely_applied = (
                    any(term in status for term in ('complete', 'processed'))
                    or ('applied' in status and 'notapplied' not in status)
                )
                checks = [
                    ("Deal 4451", _number(value('originaldeal')) == 4451),
                    ("employee D. Watts", _norm(value('employee')) == 'dwatts'),
                    ("original commission paid $480", _matches_amount(value('originalcommissionpaid'), 480)),
                    ("chargeback amount $1,600", _matches_amount(value('chargebackamount'), 1600)),
                    ("formal notice date 04/24/2026", _date(value('chargebackdate')) == date(2026, 4, 24)),
                    ("offset amount $480", _matches_amount(value('offsetamount'), 480)),
                    ("planned offset pay period", bool(_norm(value('plannedoffsetpayperiod')))),
                    ("Leah Morgan confirmation requested/pending",
                     'leah' in approval and any(term in approval for term in ('request', 'pending', 'await', 'confirm'))),
                    ("pending/not-applied offset status",
                     not prematurely_applied and any(term in status for term in ('pending', 'await', 'hold', 'notapplied'))),
                ]
                missing = [label for label, ok in checks if not ok]
                if not missing:
                    return row_number, None
                target_rows.append((row_number, missing))
        if target_rows:
            return None, f"CB-2608 row(s) in {path.name} are incomplete or invalid: {target_rows}"
        return None, f"No CB-2608 row found in {path.name} under the required headers"
    finally:
        workbook.close()

def verify(workspace_path, external_services_path=None):
    workspace = Path(workspace_path)
    original = workspace / 'commission_control.xlsx'
    if not original.is_file():
        return {"pass": False, "score": 0.0, "feedback": "Original commission_control.xlsx not found"}
    actual_hash = hashlib.sha256(original.read_bytes()).hexdigest()
    if actual_hash != ORIGINAL_SHA256:
        return {"pass": False, "score": 0.0, "feedback": "Original commission_control.xlsx was overwritten; SOP §9.4 requires a suffixed revision"}

    revisions = sorted(
        path for path in workspace.rglob('commission_control*.xlsx')
        if path.resolve() != original.resolve() and path.stem.casefold() != 'commission_control'
    )
    if not revisions:
        return {"pass": False, "score": 0.0, "feedback": "No suffixed commission_control revision found (for example commission_control_v2.xlsx)"}

    failures = []
    for revision in revisions:
        row_number, error = _inspect_revision(revision)
        if row_number is not None:
            return {"pass": True, "score": 1.0, "feedback": f"Original preserved and complete pending CB-2608 offset found in {revision.name}, Commission Control row {row_number}."}
        failures.append(error)
    return {"pass": False, "score": 0.0, "feedback": "; ".join(failures)}

